{
  "headline": "FDA's records trace our supply to a plant classified OAI 2230 days after the shortage posting",
  "headline_cites": ["D18"],
  "sentences": [
    {
      "text": "FDA first posted the ropivacaine hydrochloride shortage on 2018-03-23 and it remains current as of 2026-10-21.",
      "cites": ["E44", "D19"]
    },
    {
      "text": "The shortage listing includes Fresenius Kabi USA, LLC with an initial posting date of 2018-03-23.",
      "cites": ["E41"]
    },
    {
      "text": "Fresenius Kabi USA, LLC received an OAI classification letter dated 2024-04-30, which is 2230 days after the shortage posting.",
      "cites": ["D18"]
    },
    {
      "text": "A second OAI classification letter to Fresenius Kabi USA, LLC is dated 2024-05-22, 2252 days after the posting.",
      "cites": ["D17"]
    },
    {
      "text": "The Fresenius Kabi USA, LLC plant (FEI 1450022) is named on the product label as a registered plant for manufacture and analysis.",
      "cites": ["E28"]
    },
    {
      "text": "Corvale East has 9 days of 2 mg/mL, 20 mL vials on hand and Corvale General has 15 days and can spare 7 vials while keeping two weeks.",
      "cites": ["D3", "D4", "D20"]
    },
    {
      "text": "The rule-based best option is to transfer 7 vials of 2 mg/mL, 20 mL from Corvale General to Corvale East, which would bring Corvale East to 10 days on hand.",
      "cites": ["D20"]
    }
  ]
}
